def to_int(text):
    try:
        return int(text)
    except ValueError:
        return 0

print(to_int("12"))
print(to_int("abc"))

def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return None

print(safe_divide(10, 4))
print(safe_divide(1, 0))
